//! Convolutions where the indices multiply: `c[k] = sum_{i * j = k} a[i] b[j]` in the ring `Z/m`,
//! with values modulo 998244353.
//!
//! * [`mul_mod_prime_convolution`] (`m = p` prime): index 0 absorbs everything and is handled with
//!   sums; the non-zero residues are a cyclic group generated by a primitive root `g`, so taking
//!   discrete logs turns the product into a cyclic convolution of length `p - 1`.
//! * [`mul_mod_pow2_convolution`] (`m = 2^n`): write `i = 2^a u` with `u` odd. The odd residues
//!   modulo `2^M` are `{+-5^t}` (a group `Z/2 x Z/2^{M-2}`), so for every pair of 2-adic valuations
//!   `(a, b)` the odd parts, folded modulo `2^M` with `M = n - a - b`, multiply like a 2 x `2^{M-2}`
//!   cyclic convolution; the result lands on `2^{a+b} w`. Pairs with `a + b >= n` all give 0.
//!   Cost `O(n 2^n)` up to the NTT logarithm.
//!
//! # Example
//!
//! ```
//! use multiplicative_convolution::{mul_mod_pow2_convolution, mul_mod_prime_convolution};
//!
//! // Z/5: 2 * 3 = 1, 2 * 2 = 4, ...
//! let c = mul_mod_prime_convolution(5, &[0, 0, 1, 0, 0], &[0, 0, 0, 1, 0]);
//! assert_eq!(c, vec![0, 1, 0, 0, 0]);
//! // Z/4 with a = b = [0, 0, 1, 1]: 2*2 = 0, 3*3 = 1, 2*3 = 3*2 = 2
//! let c = mul_mod_pow2_convolution(2, &[0, 0, 1, 1], &[0, 0, 1, 1]);
//! assert_eq!(c, vec![1, 1, 2, 0]);
//! ```

use convolution::convolution;
use number_theory::primitive_root;

const MOD: u64 = 998_244_353;

fn add(a: u32, b: u32) -> u32 {
    let s = a as u64 + b as u64;
    (if s >= MOD { s - MOD } else { s }) as u32
}

fn sum(v: &[u32]) -> u32 {
    v.iter().fold(0, |s, &x| add(s, x))
}

/// `c[k] = sum_{i j = k (mod p)} a[i] b[j] mod 998244353` for a prime `p`; `a` and `b` have length
/// `p` and entries below 998244353.
pub fn mul_mod_prime_convolution(p: usize, a: &[u32], b: &[u32]) -> Vec<u32> {
    assert!(p >= 2 && a.len() == p && b.len() == p, "need sequences of length p = {p}");
    let g = primitive_root(p as u64) as usize;
    // log table: log[g^e] = e
    let mut log = vec![0usize; p];
    let mut x = 1usize;
    for e in 0..p - 1 {
        log[x] = e;
        x = x * g % p;
    }
    let mut pow = vec![0usize; p - 1];
    let mut x = 1usize;
    for slot in pow.iter_mut() {
        *slot = x;
        x = x * g % p;
    }
    let (mut fa, mut fb) = (vec![0u32; p - 1], vec![0u32; p - 1]);
    for i in 1..p {
        fa[log[i]] = a[i];
        fb[log[i]] = b[i];
    }
    let lin = convolution(&fa, &fb);
    let mut c = vec![0u32; p];
    for (t, &v) in lin.iter().enumerate() {
        let k = pow[t % (p - 1)];
        c[k] = add(c[k], v);
    }
    // index 0: a_0 * (sum b) + (sum a) * b_0 - a_0 * b_0
    let (sa, sb) = (sum(a) as u64, sum(b) as u64);
    let c0 = (a[0] as u64 * sb + sa * b[0] as u64 % MOD + MOD - a[0] as u64 * b[0] as u64 % MOD) % MOD;
    c[0] = c0 as u32;
    c
}

/// `c[k] = sum_{i j = k (mod 2^n)} a[i] b[j] mod 998244353` for sequences of length `2^n`.
pub fn mul_mod_pow2_convolution(n: usize, a: &[u32], b: &[u32]) -> Vec<u32> {
    let size = 1usize << n;
    assert!(a.len() == size && b.len() == size, "need sequences of length 2^{n}");
    // Per valuation v (0..n): sums of the odd parts folded modulo 2^M for every M <= n - v.
    // fold[v][M] is indexed by (odd residue) >> 1 and has 2^(M-1) entries (M >= 1).
    let build = |s: &[u32]| -> (Vec<Vec<Vec<u32>>>, Vec<u32>) {
        let mut fold = vec![Vec::new(); n];
        let mut val_sum = vec![0u32; n + 1];
        for v in 0..n {
            let top = n - v; // odd parts u < 2^top
            let mut cur = vec![0u32; 1 << (top - 1)];
            for (idx, slot) in cur.iter_mut().enumerate() {
                *slot = s[(2 * idx + 1) << v];
            }
            val_sum[v] = sum(&cur);
            let mut levels: Vec<Vec<u32>> = vec![Vec::new(); top + 1];
            levels[top] = cur;
            for m in (1..top).rev() {
                let half = 1usize << (m - 1);
                let prev = &levels[m + 1];
                let next: Vec<u32> = (0..half).map(|r| add(prev[r], prev[r + half])).collect();
                levels[m] = next;
            }
            fold[v] = levels;
        }
        val_sum[n] = s[0];
        (fold, val_sum)
    };
    let (fa, va) = build(a);
    let (fb, vb) = build(b);
    let mut c = vec![0u32; size];
    // k = 0 gets every pair with v2(i) + v2(j) >= n (the zero index counts as valuation n)
    let mut c0 = 0u64;
    for x in 0..=n {
        for y in 0..=n {
            if x + y >= n {
                c0 = (c0 + va[x] as u64 * vb[y] as u64) % MOD;
            }
        }
    }
    c[0] = c0 as u32;
    // powers of 5 modulo 2^M, M = 2..=n
    let pow5: Vec<Vec<u32>> = (0..=n)
        .map(|m| {
            if m < 2 {
                return Vec::new();
            }
            let modulus = 1u64 << m;
            let mut v = Vec::with_capacity(1 << (m - 2));
            let mut x = 1u64;
            for _ in 0..1usize << (m - 2) {
                v.push(x as u32);
                x = x * 5 % modulus;
            }
            v
        })
        .collect();
    for x in 0..n {
        for y in 0..n - x {
            let m = n - x - y; // modulus 2^m, m >= 1
            let (f, g) = (&fa[x][m], &fb[y][m]);
            let shift = x + y;
            if m == 1 {
                c[1 << shift] = add(c[1 << shift], (f[0] as u64 * g[0] as u64 % MOD) as u32);
                continue;
            }
            let modulus = 1u32 << m;
            let p5 = &pow5[m];
            let l = p5.len();
            let pick = |arr: &[u32], negate: bool| -> Vec<u32> {
                p5.iter().map(|&w| arr[(if negate { modulus - w } else { w } >> 1) as usize]).collect()
            };
            let (f0, f1, g0, g1) = (pick(f, false), pick(f, true), pick(g, false), pick(g, true));
            let (a00, a11) = (convolution(&f0, &g0), convolution(&f1, &g1));
            let (a01, a10) = (convolution(&f0, &g1), convolution(&f1, &g0));
            for t in 0..a00.len() {
                let tt = t % l;
                let plus = add(a00[t], a11[t]); // sign +: (+,+) and (-,-)
                let minus = add(a01[t], a10[t]); // sign -: mixed
                let w_plus = p5[tt] as usize;
                let w_minus = (modulus - p5[tt]) as usize;
                let (kp, km) = (w_plus << shift, w_minus << shift);
                c[kp] = add(c[kp], plus);
                c[km] = add(c[km], minus);
            }
        }
    }
    c
}
